#include <vector>
#include <iostream>

int main() {
    std::vector<int> v1 = {1, 2, 3};
    std::vector<int> v2 = {1, 2, 3, 4};
    std::vector<int> v3 = {1, 3, 0};

    // Lexicographical comparison
    std::cout << "v1 == v2: " << (v1 == v2) << " (False)\n";
    std::cout << "v1 < v2: " << (v1 < v2) << " (True, v1 is a prefix)\n";
    std::cout << "v1 < v3: " << (v1 < v3) << " (True, 2 < 3 at index 1)\n";
}
